    print("M=1: No integer solution.")

def check_m2():
    # M=2: 1/x_1 + x_1 / (1 + x_1^3 - x_1^2) = 15/16 = 0.9375
    def f(x1):
        if x1 <= 0: return float('inf')
        x2 = 1 + x1**3 - x1**2
        if x2 <= 0: return float('inf')
        return 1/x1 + x1/x2

    print("M=2 Checks:")
    for x1 in range(1, 5): # Checking small positive integers
        val = f(x1)
        print(f"x_1={x1}: Sum = {val:.4f}. Target = 0.9375")
        if abs(val - 0.9375) < 1e-3:
            print(f"Found match for x_1={x1}")

check_m1()
check_m2()

